import React, {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useState,
} from 'react';
import {
  ApiError,
  login as apiLogin,
  logout as apiLogout,
  me,
  register as apiRegister,
} from '../api/client';
import type { User } from '../api/types';
import { clearSession, getStoredUser, getToken, setSession } from './storage';

type AuthContextValue = {
  user: User | null;
  token: string | null;
  ready: boolean;
  login: (username: string, password: [REDACTED] => Promise<void>;
  register: (username: string, password: [REDACTED], displayName?: string) => Promise<void>;
  logout: () => Promise<void>;
};

const AuthContext = createContext<AuthContextValue | null>(null);

export function AuthProvider({ children }: { children: React.ReactNode }) {
  const [user, setUser] = useState<User | null>(null);
  const [token, setToken] = useState<string | null>(null);
  const [ready, setReady] = useState(false);

  useEffect(() => {
    let cancelled = false;

    void (async () => {
      try {
        const storedToken = await getToken();
        const storedUser = await getStoredUser();
        if (!storedToken) {
          return;
        }

        if (!cancelled && storedUser) {
          setToken(storedToken);
          setUser(storedUser);
        }

        try {
          const fresh = await me(storedToken);
          if (cancelled) return;
          setToken(storedToken);
          setUser(fresh);
          await setSession(storedToken, fresh);
        } catch (err) {
          if (err instanceof ApiError && err.status === 401) {
            await clearSession();
            if (!cancelled) {
              setToken(null);
              setUser(null);
            }
          }
        }
      } finally {
        if (!cancelled) {
          setReady(true);
        }
      }
    })();

    return () => {
      cancelled = true;
    };
  }, []);

  const login = useCallback(async (username: string, password: [REDACTED] => {
    const res = await apiLogin(username, password);
    await setSession(res.token, res.user);
    setToken(res.token);
    setUser(res.user);
  }, []);

  const register = useCallback(
    async (username: string, password: [REDACTED], displayName?: string) => {
      const res = await apiRegister(username, password, displayName);
      await setSession(res.token, res.user);
      setToken(res.token);
      setUser(res.user);
    },
    [],
  );

  const logout = useCallback(async () => {
    const current = token;
    try {
      if (current) {
        await apiLogout(current);
      }
    } catch {
      // still clear local session
    }
    await clearSession();
    setToken(null);
    setUser(null);
  }, [token]);

  const value = useMemo(
    () => ({ user, token, ready, login, register, logout }),
    [user, token, ready, login, register, logout],
  );

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
}

export function useAuth(): AuthContextValue {
  const ctx = useContext(AuthContext);
  if (!ctx) {
    throw new Error('useAuth must be used within AuthProvider');
  }
  return ctx;
}
